def command_kind(label: str, command: list[str], project: Path) -> str:
    lowered = label.lower()
    runtime_operation = (
        command[2] if len(command) >= 3 and Path(command[0]).name in {"domainry-cli", "domainry-cli.exe"}
        and command[1] == "runtime-process" else ""
    )
    if is_managed_runtime_start_gate(label):
        if runtime_process_command(command, "start", project) is None:
            raise GateError(f"command does not prove Gate '{label}'")
        return "runtime_start"
    if is_managed_runtime_health_gate(label):
        if runtime_process_command(command, "status", project) is None:
            raise GateError(f"command does not prove Gate '{label}'")
        return "runtime_status"
    if runtime_operation in {"start", "status"}:
        raise GateError("managed Runtime start/status requires its dedicated start or current-health Gate")
    verifies_project = "project verification" in lowered or "project verify" in lowered
    packages_project = "project packaging" in lowered or "packaging pass" in lowered or "project package" in lowered
    if verifies_project and packages_project:
        raise GateError("project verification and packaging must be separate Gates")
    if verifies_project:
        if not domainry_command(command, ("project", "verify"), project):
            raise GateError(f"command does not prove Gate '{label}'")
        return "project_verify"
    if packages_project:
        if not domainry_command(command, ("project", "package"), project):
            raise GateError(f"command does not prove Gate '{label}'")
        return "project_package"
    if "project check" in lowered:
        if not domainry_command(command, ("project", "check"), project) or option_value(command, "--scope") != "actions":
            raise GateError(f"command does not prove Gate '{label}'")
        return "project_check"
    if is_source_finalization_gate(label):
        if not domainry_command(command, ("project", "source", "finalize"), project):
            raise GateError(f"command does not prove Gate '{label}'")
        return "source_finalize"
    return "generic"


def validate_command_for_gate(label: str, command: list[str], project: Path) -> str:
    kind = command_kind(label, command, project)
    if kind != "generic":
        return kind
    lowered = " ".join(command).lower()
    label_value = f" {label.lower()} "
    if "module-focused" in label_value and "test" in label_value:
        executable = Path(command[0]).name.lower()
        if executable not in {"go", "go.exe"} or len(command) < 2 or command[1] != "test":
            raise GateError(f"command does not prove Gate '{label}'")
        return kind
    allowed: list[str] = []
    for category_token, category_commands in COMMAND_CATEGORIES:
        if category_token in label_value:
            allowed.extend(category_commands)
    if "focused tests" in label_value or " tests pass" in label_value or "full tests" in label_value:
        raise GateError("command JSON state did not match expectation")
    expected_codes = sorted(set(args.expect_json_diagnostic_code))
    actual_codes = sorted({value["code"] for value in proof["diagnostics"]})
    if args.expect_json_state == "valid":
        if proof["issue_count"] != 0 or expected_codes:
            raise GateError("valid project check must have an empty diagnostic inventory")
    elif not expected_codes or actual_codes != expected_codes:
        raise GateError("invalid project check diagnostic codes did not match expectation")


def delivery_string(document: dict, key: str, maximum: int = 1024) -> str:
    value = document.get(key)
    if not isinstance(value, str) or not value or len(value) > maximum:
        raise GateError(f"delivery JSON {key} is invalid or exceeds its bound")
    if any(ord(character) < 32 for character in value):
        raise GateError(f"delivery JSON {key} contains control characters")
    return value


def delivery_sha(document: dict, key: str) -> str:
    value = delivery_string(document, key, 64)
    if not re.fullmatch(r"[0-9a-f]{64}", value):
        raise GateError(f"delivery JSON {key} is not a SHA-256")
    return value


def bounded_project_json(project: Path, relative: str) -> tuple[dict, dict]:
    item = evidence_item(project, relative)
    if item["bytes"] > MAX_EXPECTED_JSON_BYTES:
        raise GateError("delivery receipt exceeds the bounded validation limit")
    path = project / relative
    try:
        document = json.loads(path.read_text(encoding="utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise GateError("delivery receipt is not valid JSON") from error
    if not isinstance(document, dict):
        raise GateError("delivery receipt must be a JSON object")
    return document, item


def project_verification_proof(stdout: bytes, project: Path) -> dict:
    result = parse_expected_json(stdout)
    if set(result) != {
        "contract_version", "delivery_id", "receipt_path", "receipt_sha256",
        "generated_tree_sha256", "project_source_tree_sha256", "user_source_sha256",
    }:
        raise GateError("project verify JSON document does not match the supported response schema")
    if result.get("contract_version") != PROJECT_VERIFICATION_CONTRACT:
        raise GateError("project verify JSON contract did not match the actual response contract")
    if delivery_string(result, "receipt_path") != VERIFICATION_RECEIPT:
        raise GateError("project verify JSON receipt path is invalid")
    delivery_string(result, "delivery_id", 512)
    for key in ("receipt_sha256", "generated_tree_sha256", "project_source_tree_sha256", "user_source_sha256"):
        delivery_sha(result, key)
    receipt, artifact = bounded_project_json(project, VERIFICATION_RECEIPT)
    if receipt.get("contract_version") != PROJECT_VERIFICATION_CONTRACT:
        raise GateError("project verification receipt contract differs")
    if delivery_sha(receipt, "receipt_sha256") != result["receipt_sha256"]:
        raise GateError("project verification response and receipt identities differ")
    runtime_manifest_sha = delivery_sha(receipt, "runtime_manifest_sha256")
    if runtime_manifest_sha != delivery_runtime_manifest_sha(project):
        raise GateError("project verification receipt runtime manifest identity is stale")
    checks = receipt.get("checks")
    if not isinstance(checks, list) or not checks or len(checks) > 100:
        raise GateError("project verification receipt check inventory is invalid or exceeds its bound")
    names = []
    for check in checks:
        if not isinstance(check, dict) or any(key not in {"name", "status", "argv", "depends_on", "failure"} for key in check):
            raise GateError("project verification receipt has an invalid check row")
        name = delivery_string(check, "name", 256)
        if name in names or check.get("status") != "passed":
            raise GateError("project verification receipt is not one complete passing check inventory")
        names.append(name)
    return {
        **artifact,
        "contract_version": PROJECT_VERIFICATION_CONTRACT,
        "state": "passed",
        "receipt_sha256": result["receipt_sha256"],
        "runtime_manifest_sha256": runtime_manifest_sha,
        "check_count": len(checks),
        "passed_check_count": len(checks),


def command_list(args, project: Path, session: str) -> int:
    state = sync_gates(project, session, load_state(project, session))
    save(project, session, state)
    rows = [{key: gate[key] for key in ("gate_id", "stage", "label", "status")} for gate in state["gates"].values() if gate.get("active", True)]
    print(json.dumps({"contract_version": CONTRACT_VERSION, "gates": rows}, ensure_ascii=False, separators=(",", ":")))
    return 0


def command_attach(args, project: Path, session: str) -> int:
    state = sync_gates(project, session, load_state(project, session))
    gate = require_gate(state, args.gate_id)
    requirements_only = requirements_only_scope(project, session)
    if args.evidence_type not in EVIDENCE_TYPES:
        raise GateError("unsupported evidence type")
    required_type = required_evidence_type(gate["label"])
    if requirements_only and REQUIREMENT_COVERAGE_MARKER in gate["label"].lower():
        required_type = ""
    if args.status == "passed" and required_type and args.evidence_type != required_type:
        raise GateError(f"Gate requires evidence type {required_type}")
    bindings = sorted(set(args.bind))
    if any(value not in BINDINGS for value in bindings):
        raise GateError("unsupported identity binding")
    identity = identities(project)
    require_available_bindings(identity, bindings)
    evidence = [evidence_item(project, value) for value in args.evidence_path]
    for item in evidence:
        validate_receipt(project, item, args.evidence_type, gate, bindings)
    if args.status == "passed":
        if requirements_only:
            validate_requirements_database_contract(project)
        if not requirements_only:
            validate_requirement_coverage(project, gate, evidence)
        validate_source_finalization(project, gate, evidence, bindings)
        validate_gate_dependencies(project, state, gate)
        if REQUIREMENT_COVERAGE_MARKER in gate["label"].lower():
            required_binding = "requirements" if requirements_only else "source"
            if required_binding not in bindings:
                raise GateError(
                    f"all requirements checkpoint must bind the current {required_binding} identity"
                )
    machine_note = validate_frontend_not_present(project, gate, args.status)
    note = f"{args.note} {machine_note}".strip() if machine_note else args.note
    bind_gate(gate, args.status, args.evidence_type, evidence, bindings, identity, note)
    save(project, session, state)
    print(json.dumps(gate, ensure_ascii=False, separators=(",", ":")))
    return 0


def command_mark(args, project: Path, session: str) -> int:
    if args.status not in {"pending", "not_applicable"}:
        raise GateError("mark supports only pending or not_applicable; use run/attach for evidenced states")
    state = sync_gates(project, session, load_state(project, session))
    gate = require_gate(state, args.gate_id)
    if args.status == "not_applicable" and mandatory_gate(gate["label"]):
        raise GateError("mandatory Gate cannot be marked not_applicable")
    machine_note = validate_frontend_not_present(project, gate, args.status)
    note = f"{args.note} {machine_note}".strip() if machine_note else args.note
    bind_gate(gate, args.status, "", [], [], identities(project), note)
    save(project, session, state)
    print(json.dumps(gate, ensure_ascii=False, separators=(",", ":")))
    return 0


