def slug(value: str) -> str:
    normalized = re.sub(r"[^a-z0-9]+", "_", value.lower()).strip("_")
    return normalized[:48] or "gate"


def stage_from_headings(headings: dict[int, str]) -> str:
    return slug(headings.get(2, "unscoped"))


def discover_gates(content: str) -> list[dict]:
    headings: dict[int, str] = {}
    gates = []
    seen = set()
    for line_number, line in enumerate(content.splitlines(), start=1):
        heading = HEADING.match(line)
        if heading:
            level = len(heading.group(1))
            headings[level] = heading.group(2).strip()
            for key in tuple(headings):
                if key > level:
                    del headings[key]
            continue
        checkbox = CHECKBOX.match(line)
        if not checkbox:
            continue
        label = checkbox.group(4).strip()
        path = " / ".join(headings[key] for key in sorted(headings))
        raw = f"{path}\0{label}".encode("utf-8")
        gate_id = f"{stage_from_headings(headings)}.{slug(label)}.{sha256_bytes(raw)[:8]}"
        if gate_id in seen:
            raise GateError(f"duplicate generated gate ID at TODO line {line_number}")
        seen.add(gate_id)
        gates.append({
            "gate_id": gate_id,
            "stage": stage_from_headings(headings),
            "label": label,
            "line": line_number,
        })
    if not gates:
        raise GateError("session TODO contains no checkboxes")
    return gates


def load_state(project: Path, session: str) -> dict:
    path = state_path(project, session)
    if not path.exists():
        return {
            "contract_version": CONTRACT_VERSION,
            "session_id": session,
            "todo_path": f".domainry/development/{session}.md",
            "gates": {},
            "findings": {},
            "updated_at": now(),
        }
    if path.is_symlink() or not path.is_file():
        raise GateError("development gate state is unsafe")
    document = json.loads(path.read_text(encoding="utf-8"))
    if document.get("contract_version") != CONTRACT_VERSION or document.get("session_id") != session:
        raise GateError("development gate state contract differs")
    if not isinstance(document.get("gates"), dict) or not isinstance(document.get("findings"), dict):
        raise GateError("development gate state is invalid")
    return document


def sync_gates(project: Path, session: str, state: dict) -> dict:
    path = todo_path(project, session)
    discovered = discover_gates(path.read_text(encoding="utf-8"))
    active = set()
    current = identities(project)
    for item in discovered:
        gate_id = item["gate_id"]
        active.add(gate_id)
        existing = state["gates"].get(gate_id, {})
        state["gates"][gate_id] = {
            "gate_id": gate_id,
            "stage": item["stage"],
            "label": item["label"],
            "todo_line": item["line"],
            "status": existing.get("status", "pending"),
            "evidence_type": existing.get("evidence_type", ""),
            "evidence": existing.get("evidence", []),
            "bindings": existing.get("bindings", []),
            "requirements_sha": existing.get("requirements_sha", ""),
            "source_sha": existing.get("source_sha", ""),
            "blueprint_sha": existing.get("blueprint_sha", ""),
            "runtime_manifest_sha": existing.get("runtime_manifest_sha", ""),
            "runtime_cohort_sha": existing.get("runtime_cohort_sha", ""),
            "verified_at": existing.get("verified_at", ""),
            "note": existing.get("note", ""),
            "active": True,
        }
    for gate_id, gate in state["gates"].items():
        if gate_id not in active:
            gate["active"] = False
    state["current_identity"] = current
    state["updated_at"] = now()
    return state


def effective_status(gate: dict, current: dict) -> str:
    status = gate.get("status", "pending")
    if status != "passed":
        return status
    project_value = current.get("project")
    runtime_binding_sha = current.get("runtime_manifest_sha", "")
    if isinstance(project_value, Path):
        for item in gate.get("evidence", []):
            path = project_value / str(item.get("path", ""))
            if (
                path.is_symlink()
                or not path.is_file()
                or sha256_file(path) != item.get("sha256")
            ):
                return "stale"
            if gate.get("evidence_type") == "command_receipt":
                try:
                    document = command_receipt_document(project_value, item)
                except (GateError, OSError, json.JSONDecodeError):
                    return "stale"
                proof = document.get("proof", {})
                if isinstance(proof, dict) and any(
                    key in proof for key in ("project_verification", "project_package")
                ):
                    runtime_binding_sha = delivery_runtime_manifest_sha(project_value)
                artifacts = proof.values() if isinstance(proof, dict) else ()
                for artifact in artifacts:
                    if not isinstance(artifact, dict) or not artifact.get("path"):
                        continue
                    artifact_path = project_value / artifact["path"]
                    if (
                        artifact_path.is_symlink()
                        or not artifact_path.is_file()
                        or artifact.get("sha256") != sha256_file(artifact_path)
                    ):
                        return "stale"
    for binding in gate.get("bindings", []):
        key = f"{binding}_sha" if binding != "runtime" else "runtime_manifest_sha"
        current_value = runtime_binding_sha if binding == "runtime" else current.get(key)
        if not gate.get(key) or gate.get(key) != current_value:
            return "stale"
    return "passed"


