def validate_frontend_not_present(project: Path, gate: dict, status: str) -> str:
    """A frontend_not_present closure Gate is machine-checked, never
    self-reported. Returns the machine observation persisted in the Gate note."""
    if FRONTEND_NOT_PRESENT_MARKER not in str(gate.get("label", "")).lower():
        return ""
    files = frontend_source_files(project)
    if status == "passed" and files:
        raise GateError(
            "frontend_not_present claimed but frontend/src contains source files: "
            + ", ".join(files)
        )
    if status == "not_applicable" and not files:
        raise GateError(
            "frontend_not_present closure must be passed with machine-check "
            "evidence, not marked not_applicable, when no frontend/src source exists"
        )
    return f"[machine] frontend/src regular files: {len(files)} @ {now()}"


def validate_requirement_coverage(project: Path, gate: dict, evidence: list[dict]) -> None:
    label = str(gate.get("label", "")).lower()
    if REQUIREMENT_COVERAGE_MARKER not in label:
        return
    managed_evidence = (project / ".domainry" / "builder" / "evidence").resolve()
    for item in evidence:
        path = project / item["path"]
        if managed_evidence not in path.resolve().parents:
            continue
        try:
            document = json.loads(path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            continue
        items = document.get("items")
        complete_items = (
            isinstance(items, list)
            and bool(items)
            and all(
                isinstance(value, dict)
                and value.get("state") == "implemented"
                and isinstance(value.get("evidence"), dict)
                and bool(value["evidence"])
                and isinstance(value.get("gaps"), list)
                and not value["gaps"]
                for value in items
            )
        )
        if (
            document.get("contract_version") == "domainry-requirement-coverage-v1"
            and document.get("state") == "passed"
            and document.get("completion_percent") == 100
            and document.get("total_count") == len(items or [])
            and document.get("implemented_count") == len(items or [])
            and document.get("partial_count") == 0
            and document.get("missing_count") == 0
            and complete_items
        ):
            return
    raise GateError("all requirements implemented requires a current 100% requirement coverage receipt")


def is_source_finalization_gate(label: str) -> bool:
    return bool(FINALIZATION_GATE_LABEL.search(" ".join(str(label).split())))


def required_evidence_type(label: str) -> str:
    lowered = label.lower()
    if is_source_finalization_gate(label):
        return "cli_receipt"
    command_tokens = (
        "project check",
        "project verification", "project packaging",
        "managed runtime start executed once", "current managed runtime health",
        "dependency installation", "typecheck", " lint ", "lint passes",
        " tests pass", "focused tests", "full tests", "production build",
        "backend formatting", "backend vet",
    )
    if any(token in f" {lowered} " for token in command_tokens):
        return "command_receipt"
    if REQUIREMENT_COVERAGE_MARKER in lowered:
        return "cli_receipt"
    return ""


def finalization_evidence_documents(project: Path, evidence: list[dict]) -> list[dict]:
    documents = []
    for item in evidence:
        document = command_receipt_document(project, item)
        if document.get("contract_version") == COMMAND_RECEIPT_VERSION:
            proof = document.get("proof", {})
            artifact = proof.get("source_finalization_receipt", {}) if isinstance(proof, dict) else {}
            if not isinstance(artifact, dict) or artifact.get("path") != FINALIZATION_RECEIPT:
                continue
            target = project / FINALIZATION_RECEIPT
            if (
                target.is_symlink()
                or not target.is_file()
                or artifact.get("sha256") != sha256_file(target)
            ):
                continue
            documents.append(command_receipt_document(project, evidence_item(project, FINALIZATION_RECEIPT)))
        else:
            documents.append(document)
    return documents


def validate_source_finalization(project: Path, gate: dict, evidence: list[dict], bindings: list[str]) -> None:
    if not is_source_finalization_gate(gate.get("label", "")):
        return
    if "source" not in bindings:
        raise GateError("local composition finalization must bind the current source identity")
    required = {
        "backend/generated/composition/action_registry.gen.go",
        "backend/generated/composition/connector_registry.gen.go",
        "backend/generated/composition/extensions.gen.go",
    }
    for document in finalization_evidence_documents(project, evidence):
        files = document.get("files")
        owned = {
            value.get("path"): value.get("sha256")
            for value in files or []
            if isinstance(value, dict) and value.get("owner") == "local_composition"
        }
        if document.get("contract_version") == "domainry-source-finalization-receipt-v2" and required <= owned.keys():
            for relative in required:
                target = project / relative
                if target.is_symlink() or not target.is_file() or sha256_file(target) != owned[relative]:
                    break
            else:
                return
    raise GateError("local composition finalization requires the complete current finalization receipt")


def validate_gate_dependencies(project: Path, state: dict, gate: dict) -> None:
    lowered = str(gate.get("label", "")).lower()
    backend_check = any(token in lowered for token in (
        "backend formatting", "backend lint", "backend vet",
        "module-focused compile", "module-focused go tests", "module-focused tests",
        "cross-module tests", "backend focused tests", "backend full tests",
    ))
    if not backend_check:
        return
    current = dict(identities(project), project=project)
    pre_finalization_module_test = (
        gate.get("stage") in {"apply", "implement", "implementation"}
        and "module-focused" in lowered
        and "test" in lowered
    )
    if pre_finalization_module_test:
        for candidate in state["gates"].values():
            if (
                not candidate.get("active", True)
                or candidate.get("stage") != gate.get("stage")
                or candidate.get("todo_line", 0) >= gate.get("todo_line", 0)
            ):
                continue
            status = effective_status(candidate, current)
            if status in BLOCKING:
                raise GateError(
                    "pre-finalization module test Gate requires every preceding "
                    f"{gate.get('stage')} TODO Gate to be closed: "
                    f"{candidate['gate_id']} ({status})"
                )
        return
    finalization = next((
        value for value in state["gates"].values()
        if value.get("active", True) and is_source_finalization_gate(value.get("label", ""))
    ), None)
    if finalization is None or effective_status(finalization, current) != "passed":
        raise GateError("backend compile/test Gate requires a current local-composition finalization Gate")


def mandatory_gate(label: str) -> bool:
    lowered = label.lower()
    if "only-if-expected-invalid-check" in lowered:
        return False
    return bool(
        required_evidence_type(label)
        or REQUIREMENT_COVERAGE_MARKER in lowered
        or "all preceding stages complete" in lowered
        or "no open" in lowered
        or "no blocked finding" in lowered
        or "no requirement remains" in lowered
    )


